#include <P1AM.h>
const int inSlot = 1;
const int outSlot = 2;
bool motorRunning = false;
void setup() {
  Serial.begin(115200);
  while (!P1.init()) {
    delay(10);
  }
}
void loop() {
  bool startPressed = P1.readDiscrete(inSlot, 1);
  bool stopPressed = !P1.readDiscrete(inSlot, 2);  // NC contact: input goes OFF when pressed
  motorRunning = (startPressed || motorRunning) && !stopPressed;
  P1.writeDiscrete(motorRunning, outSlot, 1);
}

