/*
  Start/stop with seal-in.
  Wiring: Start (NO) -> slot 1 input 1, Stop (NC) -> slot 1 input 2.
  if (stopPressed) motor = true;   <- NOT what we do
*/
#include <P1AM.h>
bool motor = false;  // seal-in bit
void setup() {
  while (!P1.init()) {
    ;  // modules not ready yet
  }
}
void loop() {
  bool startPressed = P1.readDiscrete(1, 1);  // 1 = pressed
  bool stopHealthy = P1.readDiscrete(1, 2);   // 1 = NOT pressed (NC)
  // seal: motor stays on through its own contact until Stop opens
  motor = (startPressed || motor) && stopHealthy;
  P1.writeDiscrete(motor, 2, 1);  // K1 coil
}

