#include <P1AM.h>

const unsigned long DEBOUNCE = 50;
bool running = false;
bool startStable = false, stopStable = true;
bool startLast = false, stopLast = true;
unsigned long startT = 0, stopT = 0;

void setup() {
  while (!P1.init()) {
    ;  // wait for the modules
  }
}

void loop() {
  bool s = P1.readDiscrete(1, 1);
  bool p = P1.readDiscrete(1, 2);
  if (s != startLast) { startLast = s; startT = millis(); }
  if (p != stopLast) { stopLast = p; stopT = millis(); }
  if (millis() - startT >= DEBOUNCE) startStable = startLast;
  if (millis() - stopT >= DEBOUNCE) stopStable = stopLast;
  running = (startStable || running) && stopStable;
  P1.writeDiscrete(running, 2, 1);
}

