#include <P1AM.h>

bool motorRunning = false;
unsigned long lastFlash = 0;
bool flash = false;

void setup() {
  while (!P1.init()) {
    ;  // wait for the modules
  }
}

void loop() {
  bool startPressed = P1.readDiscrete(1, 1);
  bool stopPressed = !P1.readDiscrete(1, 2);
  motorRunning = (startPressed || motorRunning) && stopPressed;
  if (millis() - lastFlash >= 500) { lastFlash = millis(); flash = !flash; }
  P1.writeDiscrete(motorRunning, 2, 1);
  P1.writeDiscrete(motorRunning && flash, 2, 3);
}

